265	// record is the archived form of a block: the report plus the canonical
266	// swaps, so a later import can detect content conflicts. Version carries
267	// the full rule parameters used for the findings; it is nil only in
268	// archives written before rule versions existed, which are interpreted
269	// under the built-in rules.
270	type record struct {
271		ChainID     string          `json:"chainId"`
272		BlockHash   string          `json:"blockHash"`
273		BlockNumber int64           `json:"blockNumber"`
274		Swaps       []Swap          `json:"swaps"`
275		Findings    []ReportFinding `json:"findings"`
276		Version     *RuleVersion    `json:"version,omitempty"`
277	}
278	
279	func (r record) ruleVersion() RuleVersion {
280		if r.Version != nil {
281			return *r.Version
282		}
283		return BuiltinVersion()
284	}
285	
286	// queryRecord mirrors one archived record the way a report query reads it.
287	// Every business field is decoded normally, but the archived rule-version
288	// declaration is kept as its raw stored document. The decoded struct cannot
289	// tell a missing field, an explicit null or a wrong-typed value from a real
290	// one: decoding the embedded version into the struct would show a decayed
291	// report under silently zeroed parameters (enabled false, severity 0, a
292	// zero displacement multiplier), and — because a null or incomplete
293	// declaration carries no usable id — risk explaining it as the built-in
294	// rules. A zero-length Version means the "version" key is absent entirely
295	// (a value-type RawMessage is left untouched for a missing key), which
296	// alone is the legacy, pre-version format interpreted under the built-in
297	// rules; any present value — the bytes "null", {} or an object — is kept
298	// byte for byte and must be re-validated from those bytes before the
299	// report is shown.
300	type queryRecord struct {
301		ChainID     string          `json:"chainId"`
302		BlockHash   string          `json:"blockHash"`
303		BlockNumber int64           `json:"blockNumber"`
304		Swaps       []Swap          `json:"swaps"`
305		Findings    []ReportFinding `json:"findings"`
306		Version     json.RawMessage `json:"version"`
307	}
308	
309	// archivedReportVersion proves the version declaration embedded in an
310	// archived record still satisfies every registration rule, re-validating
311	// the raw document with the same parser registrations pass. A wholly
312	// absent "version" key is the only legacy shape and means the built-in
313	// rules; anything actually saved — null, an empty object, an incomplete
314	// declaration, a wrong type, an out-of-range number, an unknown or
315	// duplicated field — is corruption rather than a zero-filled or built-in
316	// parameter set. An id of "builtin" names the same saved declaration and
317	// is validated just like any other id; it never bypasses the check.
318	func archivedReportVersion(raw json.RawMessage) (RuleVersion, error) {
319		if len(raw) == 0 {
320			return BuiltinVersion(), nil
321		}
322		return ParseRuleVersion(raw)
323	}
324	
325	// proveAllReportsIntact re-validates every archived report's embedded
326	// version declaration from that record's raw stored bytes with exactly the
327	// integrity proof a report query enforces (archivedReportVersion plus
328	// corruptReportError). It is the shared gate every operation that rewrites
329	// an archive must pass while holding its write lock — suppression
330	// registration and revocation alike. A wholly absent "version" key is the
331	// one legacy shape and means the built-in rules; anything actually saved —
332	// null, an empty object, an incomplete declaration, a wrong type, an
333	// out-of-range number, an unknown rule or field, or a field repeated in one
334	// object, the case-folded and escaped spellings included — fails as
335	// ErrCorruptVersion naming the report's chain and block, the readable saved
336	// version id and the offending rule or field. Every record is opened: a
337	// report on another chain, outside the operation's coverage, or carrying no
338	// conclusions is never skipped, and a legal declaration is used exactly as
339	// saved, never completed from defaults, the currently enabled or a same-id
340	// registered version. A record whose bytes are not even a JSON object is
341	// whole-archive corruption rather than one report's damaged declaration.
342	func proveAllReportsIntact(data replayArchiveDoc) error {
343		for j, rawRec := range data.Records {
344			var rec queryRecord
345			if err := json.Unmarshal(rawRec, &rec); err != nil {
346				return fmt.Errorf("archive is corrupted: record %d: %w", j, err)
347			}
348			if _, verr := archivedReportVersion(rec.Version); verr != nil {
349				return corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, verr)
350			}
351		}
352		return nil
353	}
354	
355	// corruptReportError names the chain and block a failed report query
356	// targets, the saved version identifier when the document still carries a
357	// readable one (so corruption is not mistaken for an unregistered
358	// version), and the offending rule or field from the validation failure.
359	// It wraps both ErrCorruptVersion and the underlying cause (for example
360	// ErrDuplicateField).
361	func corruptReportError(chainID, blockHash string, raw json.RawMessage, cause error) error {
362		if id := identifiableVersionID(raw); id != "unidentifiable version" {
363			return fmt.Errorf("%w: archived report for chain %s block %s uses version %q: %w",
364				ErrCorruptVersion, chainID, blockHash, id, cause)
365		}
366		return fmt.Errorf("%w: archived report for chain %s block %s: %w",
367			ErrCorruptVersion, chainID, blockHash, cause)
368	}
369	
370	// reportFromQueryRecord builds the Report presented for one archived
371	// record, proving the complete version declaration the record archived
372	// before any conclusion is shown. A report query and an identical reimport
373	// take this same path, so a re-imported block whose content matches the
374	// archive is held to exactly the standard of a standalone report query:
375	// a wholly absent version key is the one legacy shape and means the
376	// built-in rules, while a declaration actually saved as null, as an empty
377	// object, only in part, with a wrong type or an out-of-range number, an
378	// unknown or repeated field — an id of "builtin" included — fails as
379	// ErrCorruptVersion naming the chain, the block, the readable saved id
380	// and the offending rule or field. The parameters are never zero-filled,
381	// borrowed from the enabled or a registered version, or re-detected; the
382	// archived findings, evidence and swap count are returned as stored.
383	func reportFromQueryRecord(rec *queryRecord) (Report, error) {
384		version, err := archivedReportVersion(rec.Version)
385		if err != nil {
386			return Report{}, corruptReportError(rec.ChainID, rec.BlockHash, rec.Version, err)
387		}
388		return Report{
389			ChainID:     rec.ChainID,
390			BlockHash:   rec.BlockHash,
391			BlockNumber: rec.BlockNumber,
392			SwapCount:   len(rec.Swaps),
393			Version:     version,
394			Findings:    rec.Findings,
395		}, nil
396	}
