399		return Report{
400			ChainID:     r.ChainID,
401			BlockHash:   r.BlockHash,
402			BlockNumber: r.BlockNumber,
403			SwapCount:   len(r.Swaps),
404			Version:     r.ruleVersion(),
405			Findings:    r.Findings,
406		}
407	}
