414	type archiveData struct {
415		Records []record `json:"records"`
416		// Versions and EnabledVersion are absent in archives written before
417		// rule versions existed; such archives run the built-in rules.
418		Versions       []RuleVersion `json:"versions,omitempty"`
419		EnabledVersion string        `json:"enabledVersion,omitempty"`
420		// Suppressions and AlertRecords are absent in archives written before
421		// offline alerting existed; such archives simply have no registered
422		// conditions and no processing history.
423		Suppressions []Suppression      `json:"suppressions,omitempty"`
424		AlertRecords []ProcessingRecord `json:"alerts,omitempty"`
425		// Reviews is absent in archives written before manual reviews existed;
426		// every conclusion then behaves as unreviewed.
