430	// readArchiveBytes returns the exact bytes of the archive file, or nil
431	// when no archive exists yet.
432	func readArchiveBytes(dir string) ([]byte, error) {
433		raw, err := os.ReadFile(filepath.Join(dir, archiveFileName))
434		if errors.Is(err, os.ErrNotExist) {
435			return nil, nil
436		}
437		if err != nil {
438			return nil, err
439		}
440		return raw, nil
441	}
442	
443	func readArchive(dir string) (archiveData, error) {
444		raw, err := readArchiveBytes(dir)
445		if err != nil {
446			return archiveData{}, err
447		}
448		if raw == nil {
449			return archiveData{Records: []record{}}, nil
450		}
451		var data archiveData
452		if err := json.Unmarshal(raw, &data); err != nil {
453			return archiveData{}, fmt.Errorf("archive is corrupted: %w", err)
454		}
455		return data, nil
456	}
