458	// replayArchiveDoc mirrors the archive file the way a replay reads and
459	// writes it: every record and every registered version is kept as its raw
460	// stored document, while suppressions, alert records and reviews are fully
461	// decoded. A corrupt document — a wrong-typed field, say — then cannot
462	// break the read or masquerade as whole-archive corruption; the version
463	// this run selects is judged on its own by intactVersion, and an already
464	// archived block whose content matches the input is judged on its own from
465	// its record's raw bytes exactly the way a report query proves it, rather
466	// than decoded into silently zeroed parameters or a null-explained
467	// built-in report. Entries the run does not touch are written back byte
468	// for byte: a replay never repairs, completes or drops a stored record or
469	// version, not even a corrupt one.
470	type replayArchiveDoc struct {
471		Records        []json.RawMessage  `json:"records"`
472		Versions       []json.RawMessage  `json:"versions,omitempty"`
473		EnabledVersion string             `json:"enabledVersion,omitempty"`
474		Suppressions   []Suppression      `json:"suppressions,omitempty"`
475		AlertRecords   []ProcessingRecord `json:"alerts,omitempty"`
476		Reviews        []ReviewObject     `json:"reviews,omitempty"`
477	}
478	
479	// writeArchiveAtomic replaces the archive file in one rename, so a crash
480	// can only expose the previous or the next complete commit, never a half
481	// written file.
482	func writeArchiveAtomic(dir string, data any) error {
483		raw, err := json.MarshalIndent(data, "", "  ")
484		if err != nil {
485			return err
486		}
487		tmp := filepath.Join(dir, archiveFileName+".tmp")
488		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
489		if err != nil {
490			return err
491		}
492		if _, err := f.Write(raw); err != nil {
493			f.Close()
494			os.Remove(tmp)
495			return err
496		}
497		if err := f.Sync(); err != nil {
498			f.Close()
499			os.Remove(tmp)
500			return err
501		}
502		if err := f.Close(); err != nil {
503			os.Remove(tmp)
504			return err
505		}
506		if err := os.Rename(tmp, filepath.Join(dir, archiveFileName)); err != nil {
507			os.Remove(tmp)
508			return err
509		}
510		if d, err := os.Open(dir); err == nil {
511			d.Sync()
512			d.Close()
513		}
514		return nil
515	}
516	
517	// lockArchive takes an flock on the archive's lock file. The lock is
518	// released automatically if the process dies, so no stale locks survive.
519	func lockArchive(dir string, how int) (*os.File, error) {
520		f, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
521		if err != nil {
522			return nil, err
523		}
524		if err := syscall.Flock(int(f.Fd()), how); err != nil {
525			f.Close()
526			if errors.Is(err, syscall.EWOULDBLOCK) {
527				return nil, ErrBusy
528			}
529			return nil, err
530		}
531		return f, nil
532	}
