3	// Regression coverage for `reviews submit` (SubmitReview) against an
4	// archived report whose saved rule-version declaration has decayed since
5	// the report was written. Every other read path — `report`, `compare`,
6	// `alerts generate`, `reviews history`, `reviews evaluate` and an
7	// identical-block replay — re-proves the declaration embedded in a report
8	// before using it; a review submission used to be the one gap. It decoded
9	// records with the version pointer, so a written "version":null was
10	// explained as the built-in rules and an incomplete declaration came back
11	// with silently zeroed parameters, and accepting the submission re-encoded
12	// that record and stripped the damage out of the archive.
13	//
14	// Once a submission finds its target original conclusion it must now first
15	// prove — exactly the way a `report` query does — that the declaration the
16	// conclusion's report archived still carries a non-empty id, both rules
17	// with a boolean enabled and an integer severity 1-5, and a displacement
18	// multiplier 2-100. Only an old-format record with no version key at all
19	// keeps the built-in interpretation. On corruption the whole submission
20	// fails with ErrCorruptVersion: no result, no consumed submission id, no
21	// revision or object-version change, and an archive left byte for byte —
22	// including when the submission is an identical retry carrying a
23	// submissionId already stored.
24	
25	import (
26		"encoding/json"
27		"errors"
28		"os"
29		"path/filepath"
30		"reflect"
31		"strings"
32		"testing"
33	)
34	
35	// assertSubmitRefused runs one failing SubmitReview and pins the failure
36	// shape: ErrCorruptVersion wrapping the cause, never an unknown-conclusion,
37	// version-conflict or submission-id-conflict misread, naming the target
38	// chain and block plus every required extra substring, returning an empty
39	// result and leaving the archive byte-identical. A second attempt fails the
40	// same way: the declaration is neither repaired nor bypassed by a retry.
41	func assertSubmitRefused(t *testing.T, dir string, sub ReviewSubmission, want ...string) {
42		t.Helper()
43		before := readArchiveFile(t, dir)
44		res, err := SubmitReview(dir, sub)
45		if err == nil {
46			t.Fatalf("corrupt declaration accepted a review: %+v", res)
47		}
48		if !errors.Is(err, ErrCorruptVersion) {
49			t.Fatalf("error = %v, want ErrCorruptVersion", err)
50		}
51		if errors.Is(err, ErrUnknownConclusion) || errors.Is(err, ErrReviewConflict) ||
52			errors.Is(err, ErrSubmissionConflict) {
53			t.Fatalf("corrupt declaration misrouted through another failure: %v", err)
54		}
55		if !reflect.DeepEqual(res, SubmitReviewResult{}) {
56			t.Fatalf("corrupt declaration returned a partial result: %+v", res)
57		}
58		msg := err.Error()
59		for _, subStr := range append([]string{sub.ChainID, sub.BlockHash}, want...) {
60			if !strings.Contains(msg, subStr) {
61				t.Fatalf("error %q must name %q", msg, subStr)
62			}
63		}
64		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
65			t.Fatalf("failed submission changed the archive")
66		}
67		if _, err := SubmitReview(dir, sub); !errors.Is(err, ErrCorruptVersion) {
68			t.Fatalf("second submission did not fail the same way: %v", err)
69		}
70	}
71	
72	// submitTarget is a legal first-time review against the conclusion
73	// setupCorruptCompareArchive archives: a displacement on 0xv.
74	func submitTarget(id string, expected int) ReviewSubmission {
75		return reviewSub("1", "0xblk", historyTargetTx, historyTargetKind,
76			id, "alice", "confirmed bot war", ReviewStatusReal, expected)
77	}
