79	// TestSubmitReviewCorruptSavedVersionRefused runs the full corruption
80	// matrix against the declaration embedded in the target report (the
81	// registered versions stay intact): every way the saved document can stop
82	// satisfying the registration rules must fail the whole submission, naming
83	// chain, block, the readable saved id and the offending rule or field — as
84	// a first submission and as a rejudgment against an object that already
85	// carries a revision.
86	func TestSubmitReviewCorruptSavedVersionRefused(t *testing.T) {
87		for _, tc := range corruptVersionCases {
88			t.Run(tc.name, func(t *testing.T) {
89				dir := setupCorruptCompareArchive(t)
90				rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
91					tc.mutate(t, ver)
92				})
93				assertSubmitRefused(t, dir, submitTarget("s-1", 0), "candC", tc.wantErr)
94			})
95		}
96	
97		// The proof is about the original conclusion, not the review state: a
98		// rejudgment of an object that already carries a revision, and a
99		// withdrawal, fail exactly the same way before the version check can
100		// turn either one into a review-version conflict.
101		t.Run("with existing review data", func(t *testing.T) {
102			dir := setupCorruptCompareArchive(t)
103			first := submit(t, dir, submitTarget("s-1", 0))
104			if !first.Created || first.Version != 1 {
105				t.Fatalf("setup submission = %+v", first)
106			}
107			rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
108				storedRule(t, ver, "displacement")["multiplier"] = 0
109			})
110			assertSubmitRefused(t, dir, submitTarget("s-2", 1), "candC", "multiplier")
111	
112			withdrawn := reviewSub("1", "0xblk", historyTargetTx, historyTargetKind,
113				"s-3", "carol", "reset", ReviewStatusUnreviewed, 1)
114			assertSubmitRefused(t, dir, withdrawn, "candC", "multiplier")
115	
116			// Even a stale expectedVersion is refused as corruption, never as a
117			// review-version conflict: the saved basis is proved first.
118			assertSubmitRefused(t, dir, submitTarget("s-4", 0), "candC", "multiplier")
119		})
120	}
