122	// TestSubmitReviewNullAndEmptySavedVersionCorrupt pins the exact misread
123	// being fixed: version:null used to be explained as the built-in rules and
124	// to be stripped from the report by the accepting submission's rewrite, and
125	// {} or an incomplete object used to decode into zeroed parameters. All of
126	// them fail; only a wholly missing version key is the legacy built-in
127	// shape.
128	func TestSubmitReviewNullAndEmptySavedVersionCorrupt(t *testing.T) {
129		cases := []struct {
130			name        string
131			value       any
132			idReachable bool
133		}{
134			{"null", nil, false},
135			{"empty object", map[string]any{}, false},
136			{"incomplete object", map[string]any{"id": "candC"}, true},
137			{"non-object number", 5, false},
138			{"non-object string", "builtin", false},
139			{"array", []any{}, false},
140		}
141		for _, tc := range cases {
142			t.Run(tc.name, func(t *testing.T) {
143				dir := setupCorruptCompareArchive(t)
144				replaceStoredReportVersion(t, dir, "1", "0xblk", tc.value)
145				want := []string{}
146				if tc.idReachable {
147					want = append(want, "candC")
148				}
149				assertSubmitRefused(t, dir, submitTarget("s-1", 0), want...)
150			})
151		}
152	}
