154	// TestSubmitReviewBuiltinIDDoesNotBypassValidation proves an id of
155	// "builtin" names the same saved declaration as any other id and is
156	// validated in full before a review is accepted, rather than substituting
157	// the in-code builtin rules.
158	func TestSubmitReviewBuiltinIDDoesNotBypassValidation(t *testing.T) {
159		dir := setupCorruptCompareArchive(t)
160	
161		builtinFull := map[string]any{
162			"id": "builtin",
163			"rules": map[string]any{
164				"sandwich":     map[string]any{"enabled": true, "severity": 3},
165				"displacement": map[string]any{"enabled": true, "severity": 2, "multiplier": 2},
166			},
167		}
168		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinFull)
169		res, err := SubmitReview(dir, submitTarget("s-1", 0))
170		if err != nil || !res.Created || res.Version != 1 {
171			t.Fatalf("a complete builtin-id declaration must accept a review: %+v %v", res, err)
172		}
173	
174		dir2 := setupCorruptCompareArchive(t)
175		builtinDamaged := map[string]any{
176			"id": "builtin",
177			"rules": map[string]any{
178				"sandwich":     map[string]any{"enabled": true, "severity": 3},
179				"displacement": map[string]any{"enabled": true, "severity": 2},
180			},
181		}
182		replaceStoredReportVersion(t, dir2, "1", "0xblk", builtinDamaged)
183		assertSubmitRefused(t, dir2, submitTarget("s-1", 0), BuiltinVersionID, "multiplier")
184	}
