186	// TestSubmitReviewDuplicateFieldsInSavedVersionRefused covers decay
187	// registration could never have produced: a repeated field in the saved
188	// declaration, including an escaped spelling and a case-only spelling that
189	// name the same field, even when both values agree. The raw bytes are
190	// patched directly because a JSON map cannot hold two keys.
191	func TestSubmitReviewDuplicateFieldsInSavedVersionRefused(t *testing.T) {
192		cases := []struct{ name, field string }{
193			{"exact", `"severity": 4, `},
194			{"case variant", `"Severity": 4, `},
195			{"escaped", "\"se\\u0076erity\": 4, "},
196		}
197		for _, dup := range cases {
198			t.Run(dup.name, func(t *testing.T) {
199				dir := setupCorruptCompareArchive(t)
200				path := filepath.Join(dir, archiveFileName)
201				text := string(readArchiveFile(t, dir))
202				versionsAt := strings.Index(text, `"versions":`)
203				if versionsAt < 0 {
204					t.Fatal("versions section not found")
205				}
206				at := strings.Index(text[:versionsAt], `"id": "candC"`)
207				if at < 0 {
208					t.Fatal("record's embedded candC declaration not found")
209				}
210				anchor := `"severity": 4,`
211				field := strings.Index(text[at:versionsAt], anchor)
212				if field < 0 {
213					t.Fatal("severity field not found in embedded declaration")
214				}
215				pos := at + field
216				patched := text[:pos] + dup.field + text[pos:]
217				if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
218					t.Fatal(err)
219				}
220				res, err := SubmitReview(dir, submitTarget("s-1", 0))
221				if err == nil {
222					t.Fatalf("duplicate-field declaration accepted a review: %+v", res)
223				}
224				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
225					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
226				}
227				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
228					t.Fatalf("error must name candC and severity, got %v", err)
229				}
230				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
231					t.Fatalf("failed submission repaired the duplicate field")
232				}
233			})
234		}
235	}
