237	// TestSubmitReviewExplicitlyDisabledRulesAccepted proves enabled:false is
238	// a legal saved off state for a submitted review, but a disabled rule
239	// still has to carry complete, in-range parameters.
240	func TestSubmitReviewExplicitlyDisabledRulesAccepted(t *testing.T) {
241		dir := setupCorruptCompareArchive(t)
242		off := map[string]any{
243			"id": "off",
244			"rules": map[string]any{
