267	// TestSubmitReviewUsesSavedParametersNotRegistry proves accepting a review
268	// never consults the registry for the target's basis: a damaged same-id
269	// registry entry does not block an intact saved report, an intact registry
270	// cannot rescue a corrupt report, and a saved id the registry never
271	// carried still stands on its own.
272	func TestSubmitReviewUsesSavedParametersNotRegistry(t *testing.T) {
273		// Damage only the registered candC entry while the report's own embedded
274		// copy stays intact: the submission goes through and borrows nothing.
275		dir := setupCorruptCompareArchive(t)
276		if _, err := EnableVersion(dir, "twin"); err != nil {
277			t.Fatal(err)
278		}
279		rewriteStoredVersion(t, dir, "candC", func(ver map[string]any) {
