281		})
282		res, err := SubmitReview(dir, submitTarget("s-1", 0))
283		if err != nil {
284			t.Fatalf("a corrupt registry sibling must not block a review of an intact report: %v", err)
285		}
286		if !res.Created || res.Version != 1 {
287			t.Fatalf("review against intact report = %+v", res)
288		}
289		// The corrupt registry entry and the enabled marker are untouched: the
290		// submit wrote back the registry byte for byte in content and never
291		// tried to complete or strip the damaged sibling.
292		var doc replayArchiveDoc
293		if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
294			t.Fatal(err)
295		}
296		if doc.EnabledVersion != "twin" || len(doc.Versions) != 2 {
297			t.Fatalf("submit rewrote registry/enabled marker: %+v", doc)
298		}
