300		// Conversely, an intact registry cannot rescue a corrupt report.
301		dir2 := setupCorruptCompareArchive(t)
302		rewriteStoredReportVersion(t, dir2, "1", "0xblk", func(ver map[string]any) {
303			storedRule(t, ver, "displacement")["multiplier"] = 0
304		})
305		assertSubmitRefused(t, dir2, submitTarget("s-1", 0), "candC", "multiplier")
306	
307		// A complete declaration with an id the registry never carried stands
308		// on its own and accepts the review.
309		dir3 := setupCorruptCompareArchive(t)
310		stray := map[string]any{
311			"id": "never-registered",
312			"rules": map[string]any{
313				"sandwich":     map[string]any{"enabled": true, "severity": 5},
314				"displacement": map[string]any{"enabled": true, "severity": 5, "multiplier": 9},
315			},
316		}
