324	// TestSubmitReviewCorruptSiblingDoesNotBlock proves the integrity proof is
325	// scoped to the report the submission hits: a damaged declaration on
326	// another block or another chain, or a damaged registered version, never
327	// blocks a review of an intact target; and an identity the corrupt report
328	// does not carry is still an unknown conclusion and never opens that
329	// report's declaration.
330	func TestSubmitReviewCorruptSiblingDoesNotBlock(t *testing.T) {
331		dir := t.TempDir()
332		register(t, dir, candidateVersionSpec)
333		input := cmpBlockLine("1", "0xblk", 7,
334			cmpSwap("0xf", "p1", "w", 40, 0),
335			cmpSwap("0xv", "p1", "u", 10, 1),
336		) + "\n" + cmpBlockLine("1", "0other", 8,
337			cmpSwap("0g0", "p2", "w", 40, 2),
338			cmpSwap("0g1", "p2", "u", 10, 3),
339		) + "\n" + cmpBlockLine("2", "0xblk", 7,
340			cmpSwap("0q0", "p3", "w", 40, 4),
341			cmpSwap("0q1", "p3", "u", 10, 5),
342		) + "\n"
343		path := filepath.Join(t.TempDir(), "blocks.jsonl")
344		if err := os.WriteFile(path, []byte(input), 0o644); err != nil {
345			t.Fatal(err)
346		}
347		if _, err := ReplayFileWithVersion(path, dir, "candC"); err != nil {
348			t.Fatal(err)
349		}
350		register(t, dir, twinVersionSpec)
351	
352		// Damage only the same-chain sibling block.
353		rewriteStoredReportVersion(t, dir, "1", "0other", func(ver map[string]any) {
354			delete(storedRule(t, ver, "displacement"), "multiplier")
355		})
356		res, err := SubmitReview(dir, reviewSub("1", "0xblk", "0xv", SuppressDisplacement, "s-1", "a", "r", ReviewStatusReal, 0))
357		if err != nil || !res.Created {
358			t.Fatalf("a corrupt sibling block blocked the intact target: %+v %v", res, err)
359		}
360		// The damaged sibling itself still refuses, scoped to its own block.
361		assertSubmitRefused(t, dir, reviewSub("1", "0other", "0g1", SuppressDisplacement, "s-2", "a", "r", ReviewStatusReal, 0), "candC", "multiplier")
362	
363		// Damage the same-hash block on another chain: chain 1's target stays
364		// reviewable, chain 2's fails on its own.
365		rewriteStoredReportVersion(t, dir, "2", "0xblk", func(ver map[string]any) {
366			storedRule(t, ver, "displacement")["severity"] = 0
367		})
368		if _, err := SubmitReview(dir, reviewSub("1", "0xblk", "0xv", SuppressDisplacement, "s-3", "a", "r", ReviewStatusFalsePositive, 1)); err != nil {
369			t.Fatalf("a corrupt other-chain record blocked the target: %v", err)
370		}
371		assertSubmitRefused(t, dir, reviewSub("2", "0xblk", "0q1", SuppressDisplacement, "s-4", "a", "r", ReviewStatusReal, 0), "candC", "severity")
372	
373		// A damaged registry sibling never blocks an intact saved report.
374		rewriteStoredVersion(t, dir, "twin", func(ver map[string]any) {
375			storedRule(t, ver, "displacement")["multiplier"] = 1
376		})
377		if _, err := SubmitReview(dir, reviewSub("1", "0xblk", "0xv", SuppressDisplacement, "s-5", "a", "r", ReviewStatusReal, 2)); err != nil {
378			t.Fatalf("a corrupt registered version blocked the target: %v", err)
379		}
380	
381		// An identity the corrupt report does not carry is an unknown
382		// conclusion: the wrong kind on the damaged block, a ghost tx and a
383		// block that was never archived never open the damaged declaration.
384		for _, sub := range []ReviewSubmission{
385			reviewSub("1", "0other", "0g1", SuppressSandwich, "s-6", "a", "r", ReviewStatusReal, 0),
386			reviewSub("1", "0other", "0ghost", SuppressDisplacement, "s-7", "a", "r", ReviewStatusReal, 0),
387			reviewSub("1", "0nope", "0g1", SuppressDisplacement, "s-8", "a", "r", ReviewStatusReal, 0),
388		} {
389			if _, err := SubmitReview(dir, sub); !errors.Is(err, ErrUnknownConclusion) {
390				t.Fatalf("sub %+v: got %v, want ErrUnknownConclusion", sub, err)
391			}
392		}
393	}
394	
395	// TestSubmitReviewLegacyRecordStillBuiltin proves the single carve-out: a
396	// record with no version key at all keeps accepting reviews under the
397	// built-in interpretation, and appending a revision neither adds a version
398	// key to the legacy record nor alters its conclusion, evidence or swap
399	// count.
400	func TestSubmitReviewLegacyRecordStillBuiltin(t *testing.T) {
401		dir := t.TempDir()
402		legacy := `{"records":[` +
403			`{"chainId":"1","blockHash":"0old","blockNumber":5,` +
404			`"swaps":[` +
405			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
406			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
407			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}],` +
408			`"findings":[{"kind":"sandwich","severity":3,"txHash":"0v","evidence":[` +
409			`{"TxHash":"0f","Pool":"p1","Trader":"bot","In":7,"Out":6,"GasPrice":90,"Index":0},` +
410			`{"TxHash":"0v","Pool":"p1","Trader":"user","In":5,"Out":4,"GasPrice":10,"Index":1},` +
411			`{"TxHash":"0b","Pool":"p1","Trader":"bot","In":3,"Out":5,"GasPrice":80,"Index":2}]}]}]}`
412		if err := os.WriteFile(filepath.Join(dir, archiveFileName), []byte(legacy), 0o644); err != nil {
413			t.Fatal(err)
414		}
415		sub := reviewSub("1", "0old", "0v", SuppressSandwich, "s-1", "alice", "r", ReviewStatusReal, 0)
416		res, err := SubmitReview(dir, sub)
417		if err != nil {
418			t.Fatalf("legacy record must accept a review under builtin: %v", err)
419		}
420		if !res.Created || res.Version != 1 || res.Status != ReviewStatusReal {
421			t.Fatalf("legacy submission result = %+v", res)
422		}
423		// A rejudgment appends under the same legacy built-in basis.
424		res2, err := SubmitReview(dir, reviewSub("1", "0old", "0v", SuppressSandwich, "s-2", "bob", "r2", ReviewStatusFalsePositive, 1))
425		if err != nil || !res2.Created || res2.Version != 2 {
426			t.Fatalf("legacy rejudgment = %+v %v", res2, err)
427		}
428		// The report is still queryable exactly as archived: builtin
429		// parameters, original findings and evidence, and no version key
430		// invented by the review write.
431		report, err := Query(dir, "1", "0old")
432		if err != nil {
433			t.Fatalf("legacy report must still query under builtin: %v", err)
434		}
435		if report.Version != BuiltinVersion() || len(report.Findings) != 1 ||
436			report.Findings[0].Severity != 3 || report.SwapCount != 3 {
437			t.Fatalf("legacy report changed across reviews: %+v", report)
438		}
439		var doc queryArchiveDoc
440		if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
441			t.Fatal(err)
442		}
443		if len(doc.Records) != 1 || len(doc.Records[0].Version) != 0 {
444			t.Fatalf("review appended a version key to the legacy record: %s", doc.Records[0].Version)
445		}
446	}
447	
448	// TestSubmitReviewIdempotentRetryCannotBypassCorruption is the heart of
449	// the fix: the integrity proof runs before submission-id reuse, so
450	// retrying the exact submission already stored against a report whose
451	// declaration has since decayed fails as corruption instead of returning
452	// created:false — and neither a different-content reuse (submission
453	// conflict) nor a stale expected version (review conflict) can reach its
454	// old branch either. Once the declaration is restored, the ordinary retry
455	// and rejudgment conventions apply unchanged.
456	func TestSubmitReviewIdempotentRetryCannotBypassCorruption(t *testing.T) {
457		dir := setupCorruptCompareArchive(t)
458		first := submit(t, dir, submitTarget("s-1", 0))
459		if !first.Created || first.Version != 1 {
460			t.Fatalf("setup = %+v", first)
461		}
462		rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
463			storedRule(t, ver, "displacement")["multiplier"] = 0
464		})
465	
466		// Identical retry of the stored submission: corruption, not
467		// created:false with the original revision.
468		res, err := SubmitReview(dir, submitTarget("s-1", 0))
469		if err == nil {
470			t.Fatalf("identical retry masked corruption: %+v", res)
471		}
472		if !errors.Is(err, ErrCorruptVersion) || errors.Is(err, ErrSubmissionConflict) {
473			t.Fatalf("identical retry = %v, want ErrCorruptVersion", err)
474		}
475		if res.Created || res.Revision != (ReviewRevision{}) {
476			t.Fatalf("identical retry returned a result: %+v", res)
477		}
478	
479		// Same stored id, different content: still corruption rather than a
480		// submission-id conflict.
481		different := submitTarget("s-1", 0)
482		different.Operator = "mallory"
483		if _, err := SubmitReview(dir, different); !errors.Is(err, ErrCorruptVersion) {
484			t.Fatalf("different-content reuse = %v, want ErrCorruptVersion", err)
485		}
486	
487		// A fresh rejudgment with the right current version and one with a
488		// stale base both stop at the proof.
489		if _, err := SubmitReview(dir, submitTarget("s-2", 1)); !errors.Is(err, ErrCorruptVersion) {
490			t.Fatalf("rejudgment = %v, want ErrCorruptVersion", err)
491		}
492		if _, err := SubmitReview(dir, submitTarget("s-3", 0)); !errors.Is(err, ErrCorruptVersion) {
493			t.Fatalf("stale rejudgment = %v, want ErrCorruptVersion", err)
494		}
495	
496		// Restore the declaration: the stored s-1 retry is the ordinary
497		// idempotent created:false response again, appending nothing...
498		replaceStoredReportVersion(t, dir, "1", "0xblk", map[string]any{
499			"id": "candC",
500			"rules": map[string]any{
501				"sandwich":     map[string]any{"enabled": false, "severity": 3},
502				"displacement": map[string]any{"enabled": true, "severity": 4, "multiplier": 2},
503			},
504		})
505		retry, err := SubmitReview(dir, submitTarget("s-1", 0))
506		if err != nil {
507			t.Fatalf("retry after restore: %v", err)
508		}
509		if retry.Created || retry.Version != 1 || !reflect.DeepEqual(retry.Revision, first.Revision) {
510			t.Fatalf("retry = %+v, want original revision at version 1", retry)
511		}
512		// ...and the rejudgment now appends normally.
513		rejudged, err := SubmitReview(dir, submitTarget("s-2", 1))
514		if err != nil || !rejudged.Created || rejudged.Version != 2 {
515			t.Fatalf("rejudgment after restore = %+v %v", rejudged, err)
516		}
517	}
518	
519	// TestSubmitReviewCorruptDeclarationConsumesNothing proves a refused
520	// submission rewrites nothing: the archive bytes stay identical, existing
521	// revisions and object versions survive, a failed submission id is not
522	// occupied, and the alert records the archive also carries stay byte
523	// identical in content.
524	func TestSubmitReviewCorruptDeclarationConsumesNothing(t *testing.T) {
525		dir := setupCorruptCompareArchive(t)
526		submit(t, dir, submitTarget("s-1", 0))
527		// Pre-existing alert records must survive untouched as well.
528		alerts, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
529		if err != nil {
530			t.Fatal(err)
531		}
532		if len(alerts) != 1 {
533			t.Fatalf("setup: want one alert record, got %d", len(alerts))
534		}
535		rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
536			storedRule(t, ver, "displacement")["multiplier"] = 0
537		})
538		corruptBytes := readArchiveFile(t, dir)
539	
540		for i := 0; i < 2; i++ {
541			if _, err := SubmitReview(dir, submitTarget("s-new", 1)); !errors.Is(err, ErrCorruptVersion) {
542				t.Fatalf("attempt %d: got %v, want ErrCorruptVersion", i, err)
543			}
544		}
545		if after := readArchiveFile(t, dir); !reflect.DeepEqual(corruptBytes, after) {
546			t.Fatalf("refused submissions rewrote the archive")
547		}
548		var doc rawVersionArchiveDoc
549		if err := json.Unmarshal(readArchiveFile(t, dir), &doc); err != nil {
550			t.Fatal(err)
551		}
552		if len(doc.Reviews) != 1 || len(doc.Reviews[0].Revisions) != 1 ||
553			doc.Reviews[0].Revisions[0].SubmissionID != "s-1" {
554			t.Fatalf("existing review data changed: %+v", doc.Reviews)
555		}
556	
557		// Restore the basis: the refused id is free and creates version 2
558		// against the current object, exactly as if the failed attempts never
559		// happened.
560		replaceStoredReportVersion(t, dir, "1", "0xblk", map[string]any{
561			"id": "candC",
562			"rules": map[string]any{
563				"sandwich":     map[string]any{"enabled": false, "severity": 3},
564				"displacement": map[string]any{"enabled": true, "severity": 4, "multiplier": 2},
565			},
566		})
567		res, err := SubmitReview(dir, submitTarget("s-new", 1))
568		if err != nil {
569			t.Fatalf("refused id must be free after restore: %v", err)
570		}
571		if !res.Created || res.Version != 2 || res.Revision.SubmissionID != "s-new" {
572			t.Fatalf("s-new submission = %+v, want created at version 2", res)
573		}
574		alertsAfter, err := AlertHistory(dir, "1", "ops", 0, 100)
575		if err != nil {
576			t.Fatal(err)
577		}
578		if !reflect.DeepEqual(alerts, alertsAfter) {
579			t.Fatalf("alert records changed: before %+v after %+v", alerts, alertsAfter)
580		}
581	}
